// Merge financial, operational, and market data into a single snapshot
// Falls back to safe defaults for any source that failed (continueOnFail)
const request = $('Set - Prepare Reporting Window').first().json;

const financialItem = $('Fetch Financial Metrics').first();
const operationalItem = $('Fetch Operational KPIs').first();
const marketItem = $('Fetch Market Data').first();

const financialData = (financialItem && !financialItem.json.error) ? financialItem.json : { unavailable: true };
const operationalData = (operationalItem && !operationalItem.json.error) ? operationalItem.json : { unavailable: true };
const marketData = (marketItem && !marketItem.json.error) ? marketItem.json : { unavailable: true };

return [{
  json: {
    requestId: request.requestId,
    reportDate: request.reportDate,
    requestTimestamp: request.requestTimestamp,
    lookbackDays: request.lookbackDays,
    triggerSource: request.triggerSource,
    financialData,
    operationalData,
    marketData
  }
}];

