// Parse both AI responses (anomaly detection + executive briefing) and merge into one payload
function parseJsonSafely(raw) {
  let cleaned = (raw || '').trim();
  cleaned = cleaned.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    return match ? JSON.parse(match[0]) : { error: 'Failed to parse JSON', raw: cleaned };
  }
}

const request = $('Code - Merge & Normalize Metrics').first().json;

const anomalyItem = $('AI - Detect Patterns & Anomalies').first().json;
const anomalyFindings = parseJsonSafely(anomalyItem.output || anomalyItem.response || anomalyItem.text || '');

const briefingItem = $input.first().json;
const briefing = parseJsonSafely(briefingItem.output || briefingItem.response || briefingItem.text || '');

return [{
  json: {
    success: true,
    requestId: request.requestId,
    reportDate: request.reportDate,
    requestTimestamp: request.requestTimestamp,
    triggerSource: request.triggerSource,
    executiveSummary: briefing.executiveSummary,
    overallHealthScore: briefing.overallHealthScore,
    keyHighlights: briefing.keyHighlights,
    topRisks: briefing.topRisks,
    topOpportunities: briefing.topOpportunities,
    recommendedActions: briefing.recommendedActions,
    anomalies: anomalyFindings.anomalies,
    trendSummary: anomalyFindings.trendSummary,
    dataGaps: anomalyFindings.dataGaps,
    logDate: new Date().toISOString().split('T')[0],
    logTimestamp: new Date().toISOString()
  }
}];
